const t={yingshe:{jiamihuobi:"無期限先物"},comp7:{t1:"最高の取引には調査と、その後の決断が必要です。",t2:"ここで市場を検索",t3:"世界の市場が集まる場所",t4:"5000万人のトレーダーと投資家に参加し、自分の未来を自分の手でつかみましょう。",t5:"機能を見る",t6:"市場概要",t7:"最大取引量",t8:"人気のおすすめ",t9:"時価総額ランキング",t10:"私たちを選ぶ理由",t11:"盤石なセキュリティ",t12:"ホットウォレットとコールドウォレットの分離技術、大規模なユーザー保護基金、厳格なリスク管理メカニズム",t13:"多様な資産の選択",t14:"新規コインの迅速な上場、豊富な資産、中央集権と分散型市場をつなぐ",t15:"極めてスムーズな取引体験",t16:"トップクラスの市場深度と流動性、低い取引コスト、使いやすい操作性",t17:"すべての",t18:"毎月訪れるトレーダーと投資家に愛されています",t19:"トップサイト",t20:"ユーザーが共有するカスタムスクリプトとアイデア",t21:"今すぐ取引"},jiaoyi:{zhang:"ロット"}};export{t as default};
